import type { SyncStatusFragment } from '../../api/initialisation.generated';
import type { LocaleKey } from '../../intl';

// Reference implementation of the spec-owned sync-modal model
// (spec/sync-modal) — regenerated by the nightly spec build.

type V7Status = Extract<
  SyncStatusFragment,
  { __typename: 'FullSyncStatusV7Node' }
>;
type V5V6Status = Extract<
  SyncStatusFragment,
  { __typename: 'FullSyncStatusV5V6Node' }
>;

// The generated error-variant unions, straight from the schema — no widening
// to string (kdd/type-safety).
export type SyncErrorVariant =
  | NonNullable<V7Status['error']>['variantV7']
  | NonNullable<V5V6Status['error']>['variant'];

// What a phase does, for the UI to pick its marker icon by intent
// (spec/sync-modal/ui-surface.md § Layout).
export type SyncStepKind = 'push' | 'wait' | 'pull' | 'integrate' | 'prepare';

export type SyncStep = {
  // i18n key for the step's name; consumers resolve it with t() at render.
  label: LocaleKey;
  kind: SyncStepKind;
  started: boolean;
  finished: boolean;
  done?: number;
  total?: number;
};

export type SyncError = {
  // The localisation discriminant (spec/sync-modal/contract.md § Sync runs and
  // status).
  variant: SyncErrorVariant;
  // Support-facing detail.
  fullError: string;
};

export type SyncOverview = {
  isSyncing: boolean;
  error: SyncError | undefined;
  steps: SyncStep[];
  succeeded: boolean;
  // Staleness thresholds, in DAYS since the last successful sync — consumed by
  // the chrome sync indicator's badge colouring (spec/chrome § sync indicator).
  warningThresholdDays: number;
  errorThresholdDays: number;
  // The most recent successful run (spec/sync-modal/rules.md: tracked
  // independently of the latest run; a failure never erases it).
  lastSuccessful: { started: string; finished: string } | undefined;
};

type ProgressPart =
  | {
      started: string;
      finished?: string | null;
      done?: number | null;
      total?: number | null;
    }
  | null
  | undefined;

const step = (
  label: LocaleKey,
  kind: SyncStepKind,
  part: ProgressPart
): SyncStep => ({
  label,
  kind,
  started: part != null,
  finished: part?.finished != null,
  // AC-S2: a count only where there's something to count — a phase with total
  // zero or unreported (e.g. a push with no records) shows none, as the
  // current app does. A known total with no done yet reads as 0 / N.
  done: part?.total ? (part.done ?? 0) : undefined,
  total: part?.total || undefined,
});

// The two client-side axes of the phase-visibility matrix
// (spec/sync-modal/rules.md § phase visibility); the generation axis is the
// status union branch.
export type SyncSurfaceContext = {
  // The sync modal (true) vs the initialisation screen (false).
  operational: boolean;
  // The server-role axis — src/api/serverInfo.
  centralServer: boolean;
};

// Spec (sync-modal › Phase visibility): the displayed phases, in execution
// order, per generation × surface × server role. Initialisation never pushes
// (prepare-initial exists only there); a central server has no v6 legs.
export const toSyncOverview = (
  status: SyncStatusFragment | null | undefined,
  context: SyncSurfaceContext
): SyncOverview | undefined => {
  if (status == null) return undefined;

  const { operational, centralServer } = context;
  const steps =
    status.__typename === 'FullSyncStatusV7Node'
      ? [
          ...(operational
            ? [
                step('sync.step.push', 'push', status.push),
                step(
                  'sync.step.waiting-for-integration',
                  'wait',
                  status.waitingForIntegration
                ),
              ]
            : []),
          step('sync.step.pull', 'pull', status.pull),
          step('sync.step.integration', 'integrate', status.integration),
        ]
      : [
          ...(operational
            ? []
            : [
                step(
                  'sync.step.prepare-initial',
                  'prepare',
                  status.prepareInitial
                ),
              ]),
          ...(operational && !centralServer
            ? [step('sync.step.push-v6', 'push', status.pushV6)]
            : []),
          ...(operational ? [step('sync.step.push', 'push', status.push)] : []),
          step('sync.step.pull-central', 'pull', status.pullCentral),
          step('sync.step.pull-remote', 'pull', status.pullRemote),
          ...(centralServer
            ? []
            : [step('sync.step.pull-v6', 'pull', status.pullV6)]),
          step('sync.step.integration', 'integrate', status.integration),
        ];

  const error =
    status.error == null
      ? undefined
      : {
          variant:
            status.__typename === 'FullSyncStatusV7Node'
              ? status.error.variantV7
              : status.error.variant,
          fullError: status.error.fullError,
        };

  const lastSuccessful =
    status.lastSuccessfulSync?.finished != null
      ? {
          started: status.lastSuccessfulSync.started,
          finished: status.lastSuccessfulSync.finished,
        }
      : undefined;

  return {
    isSyncing: status.isSyncing,
    error,
    steps,
    succeeded: !status.isSyncing && error == null && lastSuccessful != null,
    warningThresholdDays: status.warningThreshold,
    errorThresholdDays: status.errorThreshold,
    lastSuccessful,
  };
};

// Spec (sync-modal AC-S1): one status line, by precedence — syncing, then a
// non-zero records-to-push count, then nothing-to-push. 'waiting' covers the
// first open before any status has arrived.
export type StatusLineKind =
  'waiting' | 'syncing' | 'records-to-push' | 'nothing-to-push';

export const statusLineKind = (
  overview: SyncOverview | undefined,
  pushQueueCount: number | undefined
): StatusLineKind => {
  if (!overview) return 'waiting';
  if (overview.isSyncing) return 'syncing';
  if (pushQueueCount != null && pushQueueCount > 0) return 'records-to-push';
  return 'nothing-to-push';
};

// Spec (sync-modal AC-S3): the last-successful duration lists its non-zero
// hours and minutes followed by exact seconds — never approximated. This is
// the decomposition; the notice composes the localised unit strings.
export const syncDurationParts = (
  started: string,
  finished: string
): { hours: number; minutes: number; seconds: number } => {
  const totalSeconds = Math.max(
    0,
    Math.floor(
      (new Date(finished).getTime() - new Date(started).getTime()) / 1000
    )
  );
  return {
    hours: Math.floor(totalSeconds / 3600),
    minutes: Math.floor((totalSeconds % 3600) / 60),
    seconds: totalSeconds % 60,
  };
};
